<?php namespace App\Services; use App\Models\{Inventory,InventoryMovement,Product,StockTransfer,StockTransferItem,EmergencyPurchase,CustomerSuppliedPart}; use App\Enums\InventoryMovementType; use Illuminate\Support\Facades\DB;
class InventoryService { public function adjust(Product $product,int $branchId,float $qty,string $reason,string $type='adjustment'):Inventory{return DB::transaction(function()use($product,$branchId,$qty,$reason,$type){$i=Inventory::firstOrCreate(['product_id'=>$product->id,'branch_id'=>$branchId],['quantity'=>0]);$i->quantity+=$qty;if($i->quantity<0)abort(422,'Insufficient inventory.');$i->save();InventoryMovement::create(['product_id'=>$product->id,'branch_id'=>$branchId,'type'=>$type,'quantity'=>$qty,'unit_cost'=>$product->cost_price,'user_id'=>auth()->id(),'reason'=>$reason]);return $i;});} public function reserve(Product $product,int $branchId,float $qty):void{DB::transaction(function()use($product,$branchId,$qty){$i=Inventory::where('product_id',$product->id)->where('branch_id',$branchId)->lockForUpdate()->firstOrFail();if($i->quantity-$i->reserved_quantity<$qty)abort(422,'Insufficient available inventory.');$i->reserved_quantity+=$qty;$i->save();});} public function releaseReservation(Product $product,int $branchId,float $qty):void{DB::transaction(function()use($product,$branchId,$qty){$i=Inventory::where('product_id',$product->id)->where('branch_id',$branchId)->lockForUpdate()->firstOrFail();$i->reserved_quantity=max(0,$i->reserved_quantity-$qty);$i->save();});} public function consume(Product $product,int $branchId,float $qty,int $jobId,string $referenceType='job'):void{DB::transaction(function()use($product,$branchId,$qty,$jobId,$referenceType){$i=Inventory::where('product_id',$product->id)->where('branch_id',$branchId)->first();if($i){$i->quantity-=$qty;$i->reserved_quantity=max(0,$i->reserved_quantity-$qty);$i->save();}InventoryMovement::create(['product_id'=>$product->id,'branch_id'=>$branchId,'type'=>InventoryMovementType::SERVICE_USAGE->value,'quantity'=>-$qty,'unit_cost'=>$product->cost_price,'reference_type'=>$referenceType,'reference_id'=>$jobId,'user_id'=>auth()->id(),'reason'=>'Service usage']);});} public function restore(Product $product,int $branchId,float $qty,int $jobId,string $referenceType='job'):void{DB::transaction(function()use($product,$branchId,$qty,$jobId,$referenceType){$i=Inventory::where('product_id',$product->id)->where('branch_id',$branchId)->first();if($i){$i->quantity+=$qty;$i->save();}InventoryMovement::create(['product_id'=>$product->id,'branch_id'=>$branchId,'type'=>InventoryMovementType::RESTOCK->value,'quantity'=>$qty,'unit_cost'=>$product->cost_price,'reference_type'=>$referenceType,'reference_id'=>$jobId,'user_id'=>auth()->id(),'reason'=>'Restored from job']);});} public function checkAvailability(Product $product,int $branchId,float $qty):array{$i=Inventory::where('product_id',$product->id)->where('branch_id',$branchId)->first();$available=$i?$i->quantity-$i->reserved_quantity:0;return['available'=>$available,'required'=>$qty,'sufficient'=>$available>=$qty,'shortage'=>max(0,$qty-$available)];} public function transferStock(int $fromBranchId,int $toBranchId,array $items,int $requestedBy):StockTransfer{return DB::transaction(function()use($fromBranchId,$toBranchId,$items,$requestedBy){$transferNumber='ST-'.date('Y').'-'.str_pad(StockTransfer::whereYear('created_at',date('Y'))->count()+1,6,'0',STR_PAD_LEFT);$transfer=StockTransfer::create(['transfer_number'=>$transferNumber,'from_branch_id'=>$fromBranchId,'to_branch_id'=>$toBranchId,'status'=>'pending','requested_by'=>$requestedBy]);foreach($items as $item){$product=Product::findOrFail($item['product_id']);$availability=$this->checkAvailability($product,$fromBranchId,$item['quantity']);if(!$availability['sufficient'])abort(422,"Insufficient stock for {$product->name}. Available: {$availability['available']}, Required: {$item['quantity']}");StockTransferItem::create(['stock_transfer_id'=>$transfer->id,'product_id'=>$item['product_id'],'quantity'=>$item['quantity'],'unit_cost'=>$product->cost_price]);}return $transfer;});} public function approveTransfer(StockTransfer $transfer,int $approvedBy):void{DB::transaction(function()use($transfer,$approvedBy){$transfer->update(['status'=>'approved','approved_by'=>$approvedBy,'approved_at'=>now()]);foreach($transfer->items as $item){$this->adjust(Product::find($item->product_id),$transfer->from_branch_id,-$item->quantity,'Stock transfer to '.$transfer->toBranch->name,InventoryMovementType::TRANSFER->value);}});} public function receiveTransfer(StockTransfer $transfer,int $receivedBy):void{DB::transaction(function()use($transfer,$receivedBy){$transfer->update(['status'=>'received','received_by'=>$receivedBy,'received_at'=>now()]);foreach($transfer->items as $item){$this->adjust(Product::find($item->product_id),$transfer->to_branch_id,$item->quantity,'Stock transfer from '.$transfer->fromBranch->name,InventoryMovementType::TRANSFER->value);}});} public function recordEmergencyPurchase(int $jobId,int $productId,float $qty,float $cost,string $supplierName,string $reason):EmergencyPurchase{return DB::transaction(function()use($jobId,$productId,$qty,$cost,$supplierName,$reason){$purchase=EmergencyPurchase::create(['job_id'=>$jobId,'product_id'=>$productId,'supplier_name'=>$supplierName,'quantity'=>$qty,'cost'=>$cost,'purchased_by'=>auth()->id(),'reason'=>$reason]);return $purchase;});} public function recordCustomerSuppliedPart(int $jobId,int $productId,float $qty,string $partNumber,string $condition):CustomerSuppliedPart{return CustomerSuppliedPart::create(['job_id'=>$jobId,'product_id'=>$productId,'quantity'=>$qty,'part_number'=>$partNumber,'condition'=>$condition]);} public function getLowStockItems(int $branchId):array{return Inventory::with('product')->where('branch_id',$branchId)->whereColumn('quantity','<=','products.minimum_stock')->get()->map(function($i){return['product'=>$i->product,'current'=>$i->quantity,'minimum'=>$i->product->minimum_stock,'shortage'=>$i->product->minimum_stock-$i->quantity];})->toArray();} public function getOutOfStockItems(int $branchId):array{return Inventory::with('product')->where('branch_id',$branchId)->where('quantity',0)->get()->map(function($i){return['product'=>$i->product];})->toArray();}}
